-- 1. Coloring Book Page from a Photo
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-coloring-book-page-from-photo',
  'coloring-book-page-from-photo',
  'Coloring Book Page from a Photo',
  'Image Edits',
  $input$Turn a photo of a person into a clean printable coloring-book page$input$,
  $p$Turn the attached photo into a coloring-book page.

Keep: the person's pose, proportions, hairstyle, facial features and clothing exactly as photographed, so the page is recognisably them.

Change: render everything as clean black line art on pure white. Uniform medium-weight outlines, no shading, no hatching, no grey fills, no gradients. Simplify small details (fabric folds, hair strands) into closed shapes that are easy to colour with a pencil. Add a simple background of a few large closed shapes: a doorway arch behind the figure and two potted plants at the sides, drawn in the same line weight.

Composition: full body centred, generous white margin all round, portrait orientation. No text, no watermark, no signature.$p$,
  $w$The prompt separates what must survive (identity, pose, clothes) from what must change (rendering), which is how Images 2.5 keeps a stylised edit recognisable. "Closed shapes", "uniform line weight" and "no grey fills" are the three constraints that make a page actually printable; without them the model drifts into sketchy shading. Swap the background shapes for any scene.$w$,
  'curated',
  ARRAY['image-edit', 'line-art', 'coloring-book', 'kids', 'print', 'identity-lock']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Written for the Images 2.5 identity-preservation improvement. Trend source: the coloring-page requests common in ChatGPT photo-editing threads; no external prompt reused.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Zoom on the face and hair: closed outlines, no tonal fill. Recognisable likeness; pure black lines on white; no grey; margins clean.
Outcome: Pass on attempt 1 (Sunburst high). Likeness kept (curls, smile, tee, jeans, sneakers); uniform black outlines, no grey fills; arch and two plants as closed shapes; clean margins; no text.
Model used: sunburst; attempts: 1.
Fixtures: portrait-full
Success: Recognisable likeness; pure black lines on white; no grey; margins clean.
Likely failure: Grey shading or hatching creeps in; face simplified past recognition; text or signature added.
Check first: Zoom on the face and hair: closed outlines, no tonal fill.
Attempts: 2. Model: sunburst.
Reference inputs: A clear photo of one person, full body or head-and-shoulders.$r$,
  1,
  '/library/images-2-5/coloring-book-page-from-photo.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
