-- 2. Aged Polaroid with Light Leak
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-aged-polaroid-light-leak',
  'aged-polaroid-light-leak',
  'Aged Polaroid with Light Leak',
  'Image Edits',
  $input$Make a crisp photo look like a forgotten 1990s instant print$input$,
  $p$Turn the attached photo into a 1990s instant-film print that has been kept in a drawer for thirty years.

Keep the person, pose, framing and clothing exactly as they are.

Apply, in this order: a slight warm-magenta colour shift with lifted, milky blacks; visible film grain across the whole frame; soft focus that gets softer toward the edges; a faint yellow-orange light leak entering from the bottom-right corner and fading out by the middle of the frame; one small dust speck and one hairline scratch near the top-left. Slightly reduce contrast so highlights bloom.

Present it as the physical print: white instant-film border, wider at the bottom, sitting flat on a plain neutral surface, photographed straight on with soft even light. No handwriting on the border, no text anywhere.$p$,
  $w$Vague "vintage" asks produce a filter. Naming each artefact (colour shift, grain, edge softness, leak position, one scratch) and the order they apply in gives the model a checklist, and pinning the leak to one corner stops it flooding the face. The border-and-surface framing is what sells the physical print. Say "no handwriting" or the model adds a caption.$w$,
  'curated',
  ARRAY['image-edit', 'film', 'polaroid', 'retro', '1990s', 'photo-effect']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Adapted from the 'anti-AI aesthetic' trend described by TechRepublic (Sept 2026); prompt text is Depikt's.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Compare the face and hairline to the source. Same person and pose; leak confined to bottom-right; grain and soft edges visible; clean white border.
Outcome: Pass on attempt 1 (Sunburst high). Same person and pose; warm-magenta shift, grain, soft edges; leak confined to the bottom-right; one scratch top-left; instant-film border on a neutral surface; no caption.
Model used: sunburst; attempts: 1.
Fixtures: portrait-full
Success: Same person and pose; leak confined to bottom-right; grain and soft edges visible; clean white border.
Likely failure: Face changed; leak covering the subject; a fake caption written on the border.
Check first: Compare the face and hairline to the source.
Attempts: 2. Model: sunburst.
Reference inputs: Any sharp photo of a person.$r$,
  1,
  '/library/images-2-5/aged-polaroid-light-leak.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
  tags = EXCLUDED.tags, target_model = EXCLUDED.target_model, source_type = EXCLUDED.source_type,
