-- 4. Pet Reimagined as a Human Athlete
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-pet-as-human-marathon-runner',
  'pet-as-human-marathon-runner',
  'Pet Reimagined as a Human Athlete',
  'Image Edits',
  $input$Reimagine a dog as a human marathon runner who still looks like the dog$input$,
  $p$Reimagine the dog in the attached photo as a human marathon runner crossing a finish line.

Carry over the dog's identity into the person: the same golden-blond hair colour as the coat, warm brown eyes, a broad friendly open-mouthed grin, a slightly goofy energetic posture. Someone who knows the dog should recognise the personality.

Scene: mid-stride, arms raised, breaking a finish-line tape; a bright yellow tracksuit; a race bib on the chest with no readable number, just blurred digits; a finisher's medal already around the neck. Background: a city street race with blurred spectators and bunting, late-morning sun.

Photorealistic, 85mm lens look, shallow depth of field. No text anywhere, no logos on the clothing.$p$,
  $w$"Make my pet human" fails when the model just draws a random athlete. Mapping specific traits (coat colour to hair, expression to grin, posture to energy) gives it a bridge from the source to the person. Keeping the bib number blurred sidesteps the one place text would go wrong. Works for any pet: rewrite the four trait lines.$w$,
  'curated',
  ARRAY['image-edit', 'pet', 'transformation', 'humor', 'photorealism', 'portrait']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Adapted from the pet-to-human trend (TechRepublic, Sept 2026); prompt text is Depikt's.

SETUP PROMPT: Photorealistic photo of a golden retriever sitting on a lawn in soft morning light, facing the camera with an open-mouthed happy expression, tongue slightly out, ears relaxed, fluffy golden coat. Head-and-chest framing, shallow depth of field, green blurred garden behind. No collar text, no people.$n$,
  'approved',
  true,
  true,
  true,
  'identity',
  $r$Is it a person (not a dog in clothes) and does the hair colour match the coat? A human whose colouring and expression clearly echo the dog; finish-line scene; no readable text.
Outcome: Pass on attempt 1 (Sunburst high). A human runner whose golden hair and open grin echo the dog; yellow kit, blurred bib digits, medal, finish tape, blurred crowd; no readable text or logos.
Model used: sunburst; attempts: 1.
Success: A human whose colouring and expression clearly echo the dog; finish-line scene; no readable text.
Likely failure: Anthropomorphic dog-headed figure instead of a person; readable bib numbers or brand logos.
Check first: Is it a person (not a dog in clothes) and does the hair colour match the coat?
Attempts: 2. Model: sunburst.
Reference inputs: A clear photo of the pet, ideally facing the camera.$r$,
  1,
  '/library/images-2-5/pet-as-human-marathon-runner.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
