-- 5. Transparent Product Cutout
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-transparent-product-cutout',
  'transparent-product-cutout',
  'Transparent Product Cutout',
  'Image Edits',
  $input$Isolate a product on a transparent background with clean alpha edges$input$,
  $p$Isolate the product in the attached photo on a fully transparent background.

Keep the product itself pixel-faithful: shape, label text, colours, highlights and the subtle reflections on the metal rim. Do not redraw, restyle, straighten or recolour it.

Remove everything else: the backdrop, the surface it stands on and the contact shadow. Nothing may surround the product: no glow, no outer shadow, no soft halo, no coloured haze outside the silhouette. The product must be 100% opaque everywhere inside its outline; only the outermost one-pixel edge may be anti-aliased. Leave no white halo, no dark fringe and no leftover background pixels in the gap under the rim.

Output a PNG with real transparency, product centred, small even margin on all sides.$p$,
  $w$This is the e-commerce cutout that used to need a masking pass. Naming the artefacts to avoid (halo, fringe, leftovers in cavities) is more useful than "clean edges", because those are the three ways the model fails. Ask for real transparency, not a checkerboard: a rendered checkerboard is the classic false positive. In the API, set background to transparent as well as saying it in the prompt.$w$,
  'curated',
  ARRAY['image-edit', 'product', 'transparent', 'cutout', 'ecommerce', 'packshot']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Uses the transparent-background output added to the Images 2.5 API (OpenAI cookbook); prompt text is Depikt's.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Open on a dark background and inspect the silhouette edge. PNG with real alpha; label text unchanged; no halo; shadow removed.
Outcome: Pass on attempt 2 (Sunburst high) with the revised prompt (now the record prompt). Real alpha: 69% fully transparent, corners at 0, about 1% partial pixels at the silhouette; label unchanged; no shadow. Composited on white and dark grey with no halo. Attempt 1 with the original wording was similar but the extra 'no glow, 100% opaque' lines are kept because they cost nothing. Note: the API returns opaque pixels at alpha 253–254, not 255; harmless in use.
Model used: sunburst; attempts: 2.
Fixtures: product-packshot
Success: PNG with real alpha; label text unchanged; no halo; shadow removed.
Likely failure: Painted checkerboard instead of transparency; label re-typeset; white fringe.
Check first: Open on a dark background and inspect the silhouette edge.
Attempts: 2. Model: sunburst.
Reference inputs: A product photo on a plain background.$r$,
  1,
  '/library/images-2-5/transparent-product-cutout.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
  tags = EXCLUDED.tags, target_model = EXCLUDED.target_model, source_type = EXCLUDED.source_type,
