-- 6. Six-Expression Sticker Sheet
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-six-expression-sticker-sheet',
  'six-expression-sticker-sheet',
  'Six-Expression Sticker Sheet',
  'Open-Ended Creative',
  $input$One character, six expressions, as a transparent sticker sheet$input$,
  $p$Create a sticker sheet of one original character: a round-faced orange cat in a tiny green knitted beanie, drawn in a clean kawaii style with thick dark-brown outlines and flat colours.

Six stickers in a 3 x 2 grid, each showing the same character with a different expression, in this order: 1 delighted, 2 sleepy, 3 shocked, 4 smug, 5 crying-laughing, 6 confused. The character must be identical across all six: same beanie, same proportions, same outline weight, same palette. Only the face and small hand gestures change.

Each sticker has a thick white die-cut border with a rounded outline. Even spacing, no overlap, no text, no numbers, no background: fully transparent PNG.$p$,
  $w$Sticker packs are a consistency test disguised as a fun ask. Locking the character with a short spec (species, one accessory, outline, palette) and listing the six expressions by number is what keeps all six the same character. The white die-cut border plus transparent output is what makes them usable straight away in a chat app.$w$,
  'curated',
  ARRAY['sticker', 'character', 'transparent', 'expressions', 'kawaii', 'illustration']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original; the transparent-PNG output is an Images 2.5 API feature.$n$,
  'approved',
  true,
  true,
  false,
  'none',
  $r$Compare sticker 1 and sticker 6 side by side. Six clearly identical characters, six distinct expressions, white die-cut borders, transparent background.
Outcome: Pass on attempt 1 (Sunburst high). Six identical cats (same beanie, outline, palette) with six distinct expressions in the stated order; thick white die-cut borders; transparent PNG (corners alpha 0). A small '?' glyph on sticker 6 is a symbol, not text.
Model used: sunburst; attempts: 1.
Success: Six clearly identical characters, six distinct expressions, white die-cut borders, transparent background.
Likely failure: Beanie or proportions change between stickers; a coloured background; text or numbers.
Check first: Compare sticker 1 and sticker 6 side by side.
Attempts: 2. Model: sunburst.$r$,
  1,
  '/library/images-2-5/six-expression-sticker-sheet.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
  tags = EXCLUDED.tags, target_model = EXCLUDED.target_model, source_type = EXCLUDED.source_type,
  source_creator = EXCLUDED.source_creator, source_url = EXCLUDED.source_url,
