-- 7. Traditional Tattoo Flash Sheet
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-tattoo-flash-sheet',
  'tattoo-flash-sheet',
  'Traditional Tattoo Flash Sheet',
  'Open-Ended Creative',
  $input$American-traditional flash sheet with nine designs and no lettering$input$,
  $p$Design an American-traditional tattoo flash sheet on aged cream paper.

Nine designs arranged in a loose 3 x 3 layout with hand-placed spacing, each a self-contained tattoo: a swallow in flight, a dagger through a rose, a lighthouse with waves, a panther head, a ship's anchor with rope, a lit candle, a snake coiled around a heart, a compass rose, a single peony.

Style rules: bold black outlines of even weight, limited palette of red, golden yellow, forest green and black, solid fills with minimal shading, whip-shading only inside the black. Slight ink bleed and paper texture so it reads as a hand-painted sheet, not a vector file.

No banners with words, no lettering, no signature. Portrait orientation.$p$,
  $w$Flash is a well-defined visual language, so the prompt states its rules (line weight, four colours, whip shading) rather than adjectives like "old school". Listing nine subjects avoids the model repeating motifs, and "no banners with words" matters because traditional flash normally carries text the model would garble.$w$,
  'curated',
  ARRAY['tattoo', 'flash-sheet', 'illustration', 'traditional', 'print', 'poster']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  true,
  false,
  'none',
  $r$Count the designs and scan for any letters. Nine distinct designs in a consistent flash style; four-colour palette; no lettering.
Outcome: Pass on attempt 1 (Sunburst high). Nine distinct designs in a consistent traditional style, red/yellow/green/black palette, aged paper, no banners or lettering.
Model used: sunburst; attempts: 1.
Success: Nine distinct designs in a consistent flash style; four-colour palette; no lettering.
Likely failure: Banners with misspelled words; photographic shading; duplicated motifs.
Check first: Count the designs and scan for any letters.
Attempts: 1. Model: sunburst.$r$,
  1,
  '/library/images-2-5/tattoo-flash-sheet.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
  tags = EXCLUDED.tags, target_model = EXCLUDED.target_model, source_type = EXCLUDED.source_type,
  source_creator = EXCLUDED.source_creator, source_url = EXCLUDED.source_url,
