-- 8. Packaging Label Text Swap
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-packaging-label-text-swap',
  'packaging-label-text-swap',
  'Packaging Label Text Swap',
  'Image Edits',
  $input$Change one line of label text on a product photo and nothing else$input$,
  $p$On the attached can, change only the small line of text under the brand name from "sparkling yuzu" to "sparkling grapefruit".

Match the original typeface, weight, letter-spacing, size, colour and baseline position exactly; centre the new, longer line the same way the old one was centred.

Everything else stays identical: the brand wordmark, the cloud icon, the can's colour, the metal rim, the highlights and reflections, the shadow, the background and the framing. Do not re-render the can; treat this as a label correction.$p$,
  $w$The edit is scoped to one string and describes the typographic properties that must carry over, which is how you get a correction instead of a redesign. Quoting both the old and the new text tells the model exactly what to find and what to replace. "Do not re-render the can" is the sentence that stops it regenerating the whole object.$w$,
  'curated',
  ARRAY['image-edit', 'packaging', 'text-swap', 'exact-text', 'product', 'preserve']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Pattern drawn from the Images 2.5 'surgical packaging edit' behaviour documented in the launch post; prompt text is Depikt's.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Overlay against the source: only the sub-line should differ. Only the sub-line changed; type matches; wordmark, icon, can and lighting untouched.
Outcome: Pass on attempt 1 (Sunburst high). Only the sub-line changed to 'sparkling grapefruit' in the matching typeface, centred; wordmark, cloud icon, can, rim, shadow and background unchanged.
Model used: sunburst; attempts: 1.
Fixtures: product-packshot
Success: Only the sub-line changed; type matches; wordmark, icon, can and lighting untouched.
Likely failure: Whole label re-typeset; can colour shifts; brand name altered.
Check first: Overlay against the source: only the sub-line should differ.
Attempts: 2. Model: sunburst.
Reference inputs: A product photo with legible label text.$r$,
  1,
  '/library/images-2-5/packaging-label-text-swap.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
