-- 9. Multi-Turn Campaign Localization
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-multi-turn-campaign-localization',
  'multi-turn-campaign-localization',
  'Multi-Turn Campaign Localization',
  'Image Edits',
  $input$Translate a campaign image's copy across two turns without moving anything$input$,
  $p$Run these as separate turns on the attached campaign image, feeding each result into the next. Each turn changes only the quoted text; layout, product, photo, colours and type styling stay exactly as they are.

Turn 1: Change the headline "Bright as noon." to the French "Lumineux comme midi." and the button text "Now in stores" to "En magasin". Keep the same typeface, size, weight and positions; do not move the can or any other element.
Turn 2: Change the headline "Lumineux comme midi." to the German "Hell wie der Mittag." and the button text "En magasin" to "Jetzt im Handel". Keep the same typeface, size, weight and positions; do not move the can or any other element.$p$,
  $w$Localization is the multi-turn case that pays off most: one master image, many markets. Each turn quotes the current and the new strings and restates the preservation rule, so drift has nowhere to start. Two turns is the sweet spot; the model softens after long chains, so run one language per turn and branch from the master rather than chaining five.$w$,
  'curated',
  ARRAY['image-edit', 'multi-turn', 'localization', 'exact-text', 'campaign', 'preserve']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Structure adapted from OpenAI's multi-turn localization examples; strings and scene are Depikt's.

SETUP PROMPT: Vertical 4:5 paid-social campaign image for a sparkling yuzu drink called KUMO. A pale-yellow can with the wordmark "KUMO" stands on a sunlit concrete ledge, hard noon shadow, a slice of yuzu beside it, clear blue sky behind. Top-left, a bold navy sans-serif headline in two lines: "Bright as noon." Bottom-left, a small navy rounded button with white text "Now in stores". No other text. Clean, minimal, lots of sky.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Diff turn 2 against the master outside the two text regions. After turn 2: German headline and button, everything else pixel-close to the master; turn 1 result correct in French.
Outcome: Pass on attempt 1 (Sunburst high), two-turn chain. Turn 1: French headline and button exact, nothing moved. Turn 2: German headline and button exact, can, lemon, ledge and type styling identical to the master. No drift across the chain.
Model used: sunburst; attempts: 1.
Success: After turn 2: German headline and button, everything else pixel-close to the master; turn 1 result correct in French.
Likely failure: Can or button moves; typeface changes; a turn reverts the other string.
Check first: Diff turn 2 against the master outside the two text regions.
Attempts: 1. Model: sunburst.
Reference inputs: The master campaign image, generated with the setup prompt.$r$,
  1,
  '/library/images-2-5/multi-turn-campaign-localization.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
