-- 10. Board Game Box Cover with Exact Title
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-board-game-box-cover',
  'board-game-box-cover',
  'Board Game Box Cover with Exact Title',
  'Posters',
  $input$Square board-game box art with an exact title and player count badge$input$,
  $p$Design the top of a square board-game box.

Title, exactly: "TIDEWATER" in a tall serif with a slight sea-worn texture, set in cream across the upper third. Beneath it, smaller, in the same cream: "A game of lighthouses and lost cargo".

Illustration: a night harbour seen from above at an angle, three lighthouses sweeping beams across dark water, small cargo ships leaving glowing wakes, a coastline of stone cottages. Painterly, rich navy and teal with warm amber light, fine detail in the ships.

Bottom-right corner, a small round cream badge with three lines: "2–4", "45 MIN", "AGE 10+". Bottom-left, a thin cream frame line with no other text. Square 1:1, print-ready feel, no publisher logo.$p$,
  $w$Box art has a fixed anatomy (title zone, hero illustration, spec badge), so the prompt assigns each its region and quotes every string. Putting the numbers in a badge with three short lines keeps them legible; a sentence of numbers is where text usually breaks. Swap title, tagline and illustration for any game.$w$,
  'curated',
  ARRAY['poster', 'board-game', 'packaging', 'exact-text', 'illustration', 'typography']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  true,
  false,
  'none',
  $r$Read every string aloud. Title and tagline letter-perfect; badge shows 2–4 / 45 MIN / AGE 10+; painterly harbour.
Outcome: Pass on attempt 1 (Sunburst high). 'TIDEWATER' and the tagline letter-perfect in textured cream serif; painterly night harbour with three sweeping lighthouses and cargo ships; badge reads 2–4 / 45 MIN / AGE 10+; thin frame line; no publisher logo or extra text.
Model used: sunburst; attempts: 1.
Success: Title and tagline letter-perfect; badge shows 2–4 / 45 MIN / AGE 10+; painterly harbour.
Likely failure: Extra invented text; badge numbers wrong; title texture eats letterforms.
Check first: Read every string aloud.
Attempts: 2. Model: sunburst.$r$,
  1,
  '/library/images-2-5/board-game-box-cover.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
