-- 11. Four-Season Variant Strip from One Photo
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-four-season-cabin-strip',
  'four-season-cabin-strip',
  'Four-Season Variant Strip from One Photo',
  'Image Edits',
  $input$One cabin photo rendered as four seasons side by side, nothing else changed$input$,
  $p$Using the attached photo as the master, produce one wide image containing four equal square panels side by side, left to right: summer, autumn, winter, spring.

Every panel keeps the exact same cabin, camera position, lens, framing, porch, windows, path and tree positions as the master. Only these change per panel: foliage colour and density, ground cover (grass, fallen leaves, snow, wildflowers), sky and light (summer noon, autumn golden hour, winter overcast with snowfall, spring soft morning), and small seasonal props (a garden chair in summer, a pumpkin by the door in autumn, smoke from the chimney in winter, a bicycle in spring).

Thin white gutters between panels, no borders otherwise, no labels, no text.$p$,
  $w$One source, four outputs, one image: this shows the preservation behaviour that makes Images 2.5 useful for campaigns. Listing what may change per panel (foliage, ground, sky, one prop) and stating that everything else is locked is the whole trick. The strip format lets you check consistency by eye in a single glance.$w$,
  'curated',
  ARRAY['image-edit', 'seasons', 'variants', 'preserve', 'multi-panel', 'architecture']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original; extends the launch post's seasonal-edit example into a single comparison strip.

SETUP PROMPT: Photorealistic photo of a small timber cabin with a covered porch, two front windows and a stone chimney, seen straight on from a gravel path, a large maple tree to the left and a low wooden fence, clear summer noon light, square 1:1 framing. No people, no text.$n$,
  'approved',
  true,
  true,
  true,
  'edit_source',
  $r$Line up the porch roof edge across all four panels. Four panels, identical geometry, clearly distinct seasons, one prop each, no text.
Outcome: Pass on attempt 1 (Sunburst high). Four square panels, summer to spring, with pumpkin, chimney smoke and bicycle as props and season-correct sky and ground. Cabin, porch and path line up across panels; the winter panel sits very slightly closer than the others.
Model used: sunburst; attempts: 1.
Success: Four panels, identical geometry, clearly distinct seasons, one prop each, no text.
Likely failure: Cabin shape or camera drifts between panels; seasons blend; labels appear.
Check first: Line up the porch roof edge across all four panels.
Attempts: 2. Model: sunburst.
Reference inputs: A photo of a building or scene, generated with the setup prompt.$r$,
  1,
  '/library/images-2-5/four-season-cabin-strip.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
