-- 12. Podcast Cover Art with Exact Title
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-podcast-cover-art-exact-title',
  'podcast-cover-art-exact-title',
  'Podcast Cover Art with Exact Title',
  'Posters',
  $input$Square podcast cover that stays legible at thumbnail size$input$,
  $p$Design a square podcast cover, 1:1, that must read at 64 pixels wide.

Title, exactly: "SLOW FIELDS" in a heavy geometric sans, two stacked lines, filling the top half, in off-white. Below it, small: "a walking podcast". No other text.

Artwork: a bold flat-colour illustration of a single figure with a backpack walking along a ridge, seen from behind, against a huge low sun. Three colours only: deep forest green, burnt orange, off-white. No gradients, no photographic texture, no fine detail: every shape must survive being shrunk to an app icon.

Leave a clear margin around the title; nothing overlaps the letters.$p$,
  $w$Cover art fails at thumbnail size, so the prompt designs for the smallest case: three flat colours, one big shape, a heavy typeface, a stated pixel target. Quoting the title and forbidding other text keeps the model from adding an episode number or host name. Rewrite the title and the single figure for any show.$w$,
  'curated',
  ARRAY['poster', 'podcast', 'cover', 'exact-text', 'flat-illustration', 'branding']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  true,
  false,
  'none',
  $r$Shrink the result to 64px and read the title. Title exact and dominant; three colours; still legible when viewed small.
Outcome: Pass on attempt 1 (Sunburst high). 'SLOW FIELDS' stacked in a heavy sans filling the top half, 'a walking podcast' beneath; single walking figure against a low sun; forest green, burnt orange, off-white only; reads clearly when shrunk.
Model used: sunburst; attempts: 1.
Success: Title exact and dominant; three colours; still legible when viewed small.
Likely failure: Extra text; gradients; thin type.
Check first: Shrink the result to 64px and read the title.
Attempts: 1. Model: sunburst.$r$,
  1,
  '/library/images-2-5/podcast-cover-art-exact-title.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
