-- 13. Living Room Furniture Swap
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-living-room-furniture-swap',
  'living-room-furniture-swap',
  'Living Room Furniture Swap',
  'Image Edits',
  $input$Replace the sofa and rug in a room photo while keeping the room$input$,
  $p$In the attached living-room photo, replace two things and nothing else.

Replace the sofa with a low three-seat sofa in oatmeal bouclé with slim oak legs, same footprint and position as the original. Replace the rug with a flat-weave wool rug in a wide navy-and-cream stripe, same size and placement.

Keep everything else exactly as photographed: walls, windows, daylight direction, floor, plants, side table, lamp, artwork, ceiling and camera position. The new pieces must sit in the room with correct perspective, contact shadows and the same light falling on them as on the rest of the scene.$p$,
  $w$Interior swaps go wrong when the model redecorates the whole room. Naming the two objects, their replacements with materials, and "same footprint and position" keeps the edit surgical; the preservation list covers everything that tends to drift (light direction, plants, artwork). Ask for contact shadows explicitly or the new sofa floats.$w$,
  'curated',
  ARRAY['image-edit', 'interior', 'furniture', 'preserve', 'real-estate', 'product']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Pattern drawn from the interior-design examples in the OpenAI prompting guide; prompt text and scene are Depikt's.

SETUP PROMPT: Photorealistic interior photo of a bright living room: a grey fabric sofa against the far wall, a round patterned rug in front of it, a large window on the left with soft daylight, pale oak floor, a tall fiddle-leaf fig plant in the corner, a small walnut side table with a ceramic lamp, one framed abstract print on the wall. Eye-level, wide-angle but undistorted, 3:2 landscape. No people, no text.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Check the plant and the framed print against the source. New sofa and rug as specified, in place, correctly lit; everything else unchanged.
Outcome: Pass on attempt 1 (Sunburst high). Oatmeal bouclé sofa on oak legs in the original footprint; navy-and-cream striped flat-weave rug in place; walls, window light, plant, lamp, side table, artwork and coffee table unchanged; contact shadows correct.
Model used: sunburst; attempts: 1.
Success: New sofa and rug as specified, in place, correctly lit; everything else unchanged.
Likely failure: Wall colour, plant or artwork changes; sofa floats without shadow; window light flips.
Check first: Check the plant and the framed print against the source.
Attempts: 2. Model: sunburst.
Reference inputs: A living-room photo, generated with the setup prompt.$r$,
  1,
  '/library/images-2-5/living-room-furniture-swap.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
