-- 14. Texture-Preserving Skin Retouch
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-texture-preserving-skin-retouch',
  'texture-preserving-skin-retouch',
  'Texture-Preserving Skin Retouch',
  'Image Edits',
  $input$Professional retouch that removes blemishes but keeps real skin$input$,
  $p$Retouch the attached portrait the way a magazine retoucher would, not the way a beauty filter would.

Remove: temporary blemishes, the small spot on the cheek, minor redness, stray flyaway hairs crossing the face.

Keep: all skin texture (pores, fine lines, the natural sheen on the nose and forehead), freckles, the shape of every feature, the eye colour, the catchlights, the original lighting and colour balance. Do not slim the face, enlarge the eyes, whiten the teeth beyond their natural tone, or smooth the skin into plastic.

Even out the skin tone very gently. The result should look like the same photo on a better day.$p$,
  $w$The line between retouching and a filter is texture, so the prompt names what to remove and, in more detail, what to keep. Listing the classic filter moves (slimming, eye enlargement, plastic skin) as forbidden is what stops them. "The same photo on a better day" is a useful summary the model responds to.$w$,
  'curated',
  ARRAY['image-edit', 'retouch', 'portrait', 'skin', 'preserve', 'beauty']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.

SETUP PROMPT: Photorealistic close-up portrait of a man in his late thirties, head and shoulders, neutral expression with a slight smile, natural window light from the left, visible pores and fine lines, a few freckles across the nose, one small blemish on the right cheek, slight redness around the nose, a few flyaway hairs. Plain warm-grey background, 85mm lens look, 4:5 portrait. No text.$n$,
  'approved',
  true,
  false,
  true,
  'edit_source',
  $r$Zoom on the nose and cheek for pore texture. Blemish and redness gone; pores, freckles and lines intact; features and lighting unchanged.
Outcome: Pass on attempt 1 (Sunburst high). Cheek blemish and nose redness removed, flyaways tidied; pores, forehead lines, freckles, stubble and catchlights intact; features, colour balance and lighting unchanged; no plastic smoothing.
Model used: sunburst; attempts: 1.
Success: Blemish and redness gone; pores, freckles and lines intact; features and lighting unchanged.
Likely failure: Plastic smoothing; face reshaped; freckles removed.
Check first: Zoom on the nose and cheek for pore texture.
Attempts: 2. Model: sunburst.
Reference inputs: A close-up portrait with visible skin texture, generated with the setup prompt.$r$,
  1,
  '/library/images-2-5/texture-preserving-skin-retouch.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
  tags = EXCLUDED.tags, target_model = EXCLUDED.target_model, source_type = EXCLUDED.source_type,
  source_creator = EXCLUDED.source_creator, source_url = EXCLUDED.source_url,
