-- 15. Old Photo Restoration and Colorization
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-old-photo-restoration-colorize',
  'old-photo-restoration-colorize',
  'Old Photo Restoration and Colorization',
  'Image Edits',
  $input$Repair a creased, faded family photo and colourise it plausibly$input$,
  $p$Restore the attached old photograph in two layers of work.

Repair: remove the creases, tears, water stain and dust; rebuild the missing corner using the surrounding content; recover contrast and detail in the faded areas. Keep every face, pose, garment and background object exactly as in the original; do not reinterpret expressions or add anything that was not there.

Colourise: period-plausible, restrained colours for the 1950s: muted fabric tones, natural skin, a soft blue sky, no oversaturation. Keep the light grain of the original so it still reads as a photograph of its time, not a modern render.

Output the photo alone, straightened, without the paper border.$p$,
  $w$Restoration is two jobs, and separating them keeps the model honest: repair with strict preservation, then colour with a period brief. "Do not reinterpret expressions" matters because the model will otherwise improve faces. Keeping grain is the difference between restored and fake.$w$,
  'curated',
  ARRAY['image-edit', 'restoration', 'colorize', 'vintage', 'family', 'preserve']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original; the setup image creates the damaged source so no real family photo is needed for testing.

SETUP PROMPT: Scan of a damaged black-and-white family photograph from the 1950s: a family of four in front of a suburban house next to a parked car, parents standing, two children in front, everyone smiling at the camera. The print is faded and low-contrast, with two deep creases crossing the image, a torn-off bottom-left corner, a brown water stain top-right, scattered dust and scratches, and a scalloped white paper border. Slightly skewed on the scanner. 5:4 landscape. No text.$n$,
  'approved',
  true,
  true,
  true,
  'edit_source',
  $r$Compare each face and the car to the source. Damage gone, corner rebuilt, faces identical, plausible muted colour, grain kept.
Outcome: Pass on attempt 1 (Sunburst high). Creases, stain, dust and the torn corner repaired; straightened; paper border removed; all four faces, poses and the car unchanged; restrained 1950s colour with grain kept.
Model used: sunburst; attempts: 1.
Success: Damage gone, corner rebuilt, faces identical, plausible muted colour, grain kept.
Likely failure: Faces changed or beautified; saturated colours; new objects added.
Check first: Compare each face and the car to the source.
Attempts: 2. Model: sunburst.
Reference inputs: A scan of a damaged black-and-white photo, generated with the setup prompt.$r$,
  1,
  '/library/images-2-5/old-photo-restoration-colorize.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
  user_input = EXCLUDED.user_input, prompt = EXCLUDED.prompt, why_it_works = EXCLUDED.why_it_works,
