-- 16. Casual Photo to Studio Headshot
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-casual-photo-to-studio-headshot',
  'casual-photo-to-studio-headshot',
  'Casual Photo to Studio Headshot',
  'Image Edits',
  $input$Turn a casual full-body photo into a professional headshot without changing the person$input$,
  $p$From the attached casual photo, produce a professional studio headshot of the same person.

Identity is locked: same face, hair, skin tone, eye colour, eyebrows, smile and ears. Do not slim, smooth or age them.

Change: crop to head-and-shoulders with the eyes on the upper third; replace the outfit with a plain navy crew-neck knit; replace the background with a soft mid-grey seamless with a gentle vignette; light with a large soft key from the front-left, subtle fill and a faint hair light so the hair separates from the background. Slight shallow depth of field, 85mm look, natural colour.

Straight-on pose, relaxed shoulders, direct eye contact. No text, no logo.$p$,
  $w$Headshots from casual photos are the everyday use of identity preservation. The prompt names the identity anchors, then lists the four things a studio changes (crop, outfit, backdrop, light) so the model knows the scope. Specifying the light setup by position beats "professional lighting" every time.$w$,
  'curated',
  ARRAY['image-edit', 'headshot', 'portrait', 'identity-lock', 'linkedin', 'studio']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  false,
  true,
  'identity',
  $r$Hair texture and smile against the source. Unmistakably the same person; grey seamless; navy knit; soft studio light; no text.
Outcome: Pass on attempt 1 (Sunburst high). Unmistakably the same person (curls, brows, smile, earrings); head-and-shoulders crop, navy crew-neck knit, mid-grey seamless with vignette, soft front-left key and hair separation; no text.
Model used: sunburst; attempts: 1.
Fixtures: portrait-full
Success: Unmistakably the same person; grey seamless; navy knit; soft studio light; no text.
Likely failure: Face smoothed or reshaped; hair changed; outfit keeps the original tee.
Check first: Hair texture and smile against the source.
Attempts: 2. Model: sunburst.
Reference inputs: A casual photo where the face is clearly visible.$r$,
  1,
  '/library/images-2-5/casual-photo-to-studio-headshot.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
