-- 17. App Icon Set, One System
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-app-icon-set-six',
  'app-icon-set-six',
  'App Icon Set, One System',
  'UI Mockups',
  $input$Six app icons that share one visual system, presented on a grid$input$,
  $p$Design a set of six app icons for a fictional productivity suite, shown on one presentation board.

System: rounded-square iOS-style icons, identical corner radius, each with a single flat white glyph centred on a two-tone background (one base colour plus a slightly darker diagonal split in the lower-right). Same glyph stroke weight across all six. No text, no letters as glyphs.

The six, left to right in two rows of three, each with its base colour: Notes (paper sheet glyph, warm yellow), Calendar (grid glyph, coral red), Tasks (check circle glyph, leaf green), Timer (stopwatch glyph, indigo), Files (folder glyph, sky blue), Mail (envelope glyph, slate grey).

Present them at equal size on a plain off-white board with even spacing and a soft contact shadow under each. Nothing else on the board.$p$,
  $w$Icon sets drift when each icon is designed alone, so the prompt defines the system once (shape, radius, glyph treatment, split, stroke) and then only varies the glyph and base colour per icon. Forbidding letters as glyphs removes the one element that would break. The board layout makes consistency easy to judge.$w$,
  'curated',
  ARRAY['ui', 'app-icon', 'icon-set', 'design-system', 'branding', 'mockup']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  true,
  false,
  'none',
  $r$Compare the corner radius of icon 1 and icon 6. Six icons with identical geometry and stroke; six named glyphs and colours; no text.
Outcome: Pass on attempt 1 (Sunburst high). Six rounded squares with identical radius, white glyphs of one stroke weight, two-tone diagonal split; Notes, Calendar, Tasks, Timer, Files, Mail in the stated colours; no letters used as glyphs; soft contact shadows on an off-white board.
Model used: sunburst; attempts: 1.
Success: Six icons with identical geometry and stroke; six named glyphs and colours; no text.
Likely failure: Different corner radii or stroke weights; a letter used as a glyph; extra labels.
Check first: Compare the corner radius of icon 1 and icon 6.
Attempts: 1. Model: sunburst.$r$,
  1,
  '/library/images-2-5/app-icon-set-six.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
