-- 18. YouTube Thumbnail with Exact Title
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-youtube-thumbnail-exact-title',
  'youtube-thumbnail-exact-title',
  'YouTube Thumbnail with Exact Title',
  'Social Posts',
  $input$16:9 thumbnail with a big exact title and a clear focal object$input$,
  $p$Create a 16:9 YouTube thumbnail.

Left 60%: the text "I TESTED 5 STANDING DESKS" in a very heavy condensed sans, three stacked lines, white with a thick black outline and a subtle drop shadow, filling the height. Beneath it, smaller, in bright yellow: "one was a mistake".

Right 40%: a photorealistic standing desk at its highest position, slightly tilted toward the camera, with a red circle-and-slash icon drawn over one of its legs. Background: a clean studio wall in deep teal with a soft spotlight behind the desk.

High contrast, no other text, no faces, no logos. Everything must read at 320 pixels wide.$p$,
  $w$Thumbnails are a legibility problem, so the prompt allocates space (60/40), quotes the two strings, specifies weight, outline and colour, and sets a pixel target. A single focal object with one graphic overlay reads faster than a busy scene. Change the strings and the object; keep the layout.$w$,
  'curated',
  ARRAY['social', 'youtube', 'thumbnail', 'exact-text', 'typography', '16:9']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  false,
  false,
  'none',
  $r$Shrink to 320px and read the title. Both strings exact and huge; desk on the right; teal background; legible when small.
Outcome: Pass on attempt 1 (Sunburst high). Both strings exact: three-line white outlined title on the left, yellow 'one was a mistake' beneath; standing desk with red circle-and-slash on the right; deep teal studio wall; legible at small size; no other text.
Model used: sunburst; attempts: 1.
Success: Both strings exact and huge; desk on the right; teal background; legible when small.
Likely failure: Extra words; title wraps badly; desk too small to read.
Check first: Shrink to 320px and read the title.
Attempts: 2. Model: sunburst.$r$,
  1,
  '/library/images-2-5/youtube-thumbnail-exact-title.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
