-- 19. Holiday Card with Exact Greeting
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-holiday-card-exact-greeting',
  'holiday-card-exact-greeting',
  'Holiday Card with Exact Greeting',
  'Posters',
  $input$Printable 5x7 holiday card with a hand-lettered exact greeting$input$,
  $p$Design the front of a 5 x 7 portrait holiday card.

Illustration: a cosy winter scene in a warm gouache style, a small red cottage in deep snow at dusk, warm light in every window, a string of lights across the porch, pine trees behind, big soft snowflakes falling. Limited palette of cream, deep green, warm red and gold.

Greeting, exactly, in hand-lettered brush script in cream across the sky area: "Warm wishes from our home to yours". Nothing else written anywhere on the card.

Leave a quarter-inch clean margin for print bleed. No border line, no year, no names.$p$,
  $w$Cards need one illustration and one line of text that the printer will not have to fix. Quoting the greeting, naming the lettering style and placing it in the sky (where there is no detail to collide with) keeps it clean. The explicit "no year, no names" stops the model helpfully adding both.$w$,
  'curated',
  ARRAY['poster', 'holiday-card', 'greeting', 'exact-text', 'gouache', 'print']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  true,
  false,
  'none',
  $r$Read the greeting word by word. Greeting exact in brush script, in the sky; gouache cottage scene; nothing else written.
Outcome: Pass on attempt 1 (Sunburst high). Greeting exact in cream brush script placed in the sky; gouache red cottage at dusk with lit windows, porch lights, pines and falling snow; limited palette; no year, names or border line.
Model used: sunburst; attempts: 1.
Success: Greeting exact in brush script, in the sky; gouache cottage scene; nothing else written.
Likely failure: Extra text (a year, a name); greeting misspelled; lettering overlapping the cottage.
Check first: Read the greeting word by word.
Attempts: 2. Model: sunburst.$r$,
  1,
  '/library/images-2-5/holiday-card-exact-greeting.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
  slug = EXCLUDED.slug, title = EXCLUDED.title, category = EXCLUDED.category,
