-- 20. Certificate Template with Exact Names
INSERT INTO public.curated_prompts (
  id, slug, title, category, user_input, prompt, why_it_works, source, tags, target_model,
  source_type, source_creator, source_url, source_notes, status, generation_ready, gallery_ready,
  needs_reference_images, reference_mode, review_notes, result_count, thumbnail_url, created_at, updated_at
) VALUES (
  'images25-certificate-template-exact-names',
  'certificate-template-exact-names',
  'Certificate Template with Exact Names',
  'Posters',
  $input$Landscape certificate with exact recipient, course and date text$input$,
  $p$Design a landscape certificate of completion on cream paper with a fine navy and gold guilloche border.

Text, top to bottom, all centred, exactly as written:
"CERTIFICATE OF COMPLETION" (small caps, letter-spaced, navy)
"This certifies that" (small italic serif)
"Maya Okonkwo" (large elegant script, gold)
"has successfully completed the course" (small italic serif)
"Foundations of Visual Design" (bold serif, navy)
"12 September 2026" (small serif)

Bottom-left, a signature line with "Course Director" beneath it. Bottom-right, an embossed gold circular seal with a laurel motif and no text inside. Balanced whitespace, nothing else on the page.$p$,
  $w$Certificates are pure exact-text work: six strings, each with a role and a type treatment. Listing them in order with their styles is far more reliable than describing the document. The seal is told to carry no text because seals are where invented letters appear. Swap the three variable lines for any recipient.$w$,
  'curated',
  ARRAY['poster', 'certificate', 'exact-text', 'typography', 'document', 'print']::text[],
  'gpt-image-2.5',
  'depikt_original',
  'Depikt',
  NULL,
  $n$Depikt original.$n$,
  'approved',
  true,
  false,
  false,
  'none',
  $r$Read the name and the date. All six strings letter-perfect in the stated styles; seal with no text; clean border.
Outcome: Pass on attempt 1 (Sunburst high). All six strings letter-perfect in the stated treatments (letter-spaced small caps, italic serif, gold script name, bold serif course, date); guilloche navy-and-gold border; signature line with 'Course Director'; embossed gold laurel seal with no text; nothing else on the page.
Model used: sunburst; attempts: 1.
Success: All six strings letter-perfect in the stated styles; seal with no text; clean border.
Likely failure: A string altered; text inside the seal; a misspelled name.
Check first: Read the name and the date.
Attempts: 2. Model: sunburst.$r$,
  1,
  '/library/images-2-5/certificate-template-exact-names.webp',
  '2026-09-10T03:00:00.000Z',
  '2026-09-10T03:00:00.000Z'
) ON CONFLICT (id) DO UPDATE SET
